sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// The g_scratchpad will be used by client script in the Hoc Investigation Case table.
	// It is used for instance by the script "Hide tab based on roles".
	g_scratchpad.hasOHSGroups = gs.getUser().isMemberOf('CEH-HRS-OHS-Advisor');
	g_scratchpad.hasOHSAdmin = gs.getUser().isMemberOf('CEH-HRS-OHS-Admin');
	g_scratchpad.isDeveloper = gs.getUser().isMemberOf('CEH-Developer');

})(current, previous);
